use std::alloc::{alloc, dealloc, Layout};
use std::ptr;

const TOKEN_SIZE: usize = 256;
const TAG_AUTHENTICATED: usize = 0x1;
const TAG_REFRESHABLE: usize = 0x2;

/// Tagged pointer implementation for token metadata.
/// Low 2 bits store flags since allocations are at least 4-byte aligned.
struct TaggedPtr {
    bits: usize,
}

impl TaggedPtr {
    fn new(ptr: *mut u8) -> Self {
        TaggedPtr { bits: ptr as usize }
    }

    fn null() -> Self {
        TaggedPtr { bits: 0 }
    }

    fn set_tag(&mut self, tag: usize) {
        self.bits |= tag & 0x3;
    }

    fn clear_tag(&mut self, tag: usize) {
        self.bits &= !(tag & 0x3);
    }

    fn get_ptr(&self) -> *mut u8 {
        (self.bits & !0x3) as *mut u8
    }

    fn is_null(&self) -> bool {
        // Check if the pointer portion is null
        self.bits & !0x3 == 0
    }

    fn set_null(&mut self) {
        // Clear the pointer but preserve tag bits for state tracking
        self.bits &= 0x3;
    }

    fn has_tag(&self, tag: usize) -> bool {
        self.bits & tag != 0
    }

    fn raw_bits(&self) -> usize {
        self.bits
    }
}

struct SessionToken {
    data: TaggedPtr,
    layout: Layout,
    generation: u32,
}

impl SessionToken {
    fn allocate() -> Self {
        let layout = Layout::from_size_align(TOKEN_SIZE, 4).unwrap();
        let ptr = unsafe { alloc(layout) };
        if ptr.is_null() {
            panic!("allocation failed");
        }
        // Initialize token data
        unsafe { ptr::write_bytes(ptr, 0xAA, TOKEN_SIZE); }
        let mut tagged = TaggedPtr::new(ptr);
        tagged.set_tag(TAG_REFRESHABLE);
        SessionToken {
            data: tagged,
            layout,
            generation: 1,
        }
    }

    fn is_active(&self) -> bool {
        !self.data.is_null() && self.generation > 0
    }

    fn mark_authenticated(&mut self) {
        self.data.set_tag(TAG_AUTHENTICATED);
    }

    fn release(&mut self) {
        let ptr = self.data.get_ptr();
        if !ptr.is_null() {
            unsafe { dealloc(ptr, self.layout); }
            self.data.set_null(); // Nulls pointer portion, preserves tags
            self.generation = 0;
        }
    }

    fn needs_refresh(&self) -> bool {
        self.data.has_tag(TAG_REFRESHABLE)
    }
}

struct AuthManager {
    token: SessionToken,
    failed_attempts: u32,
    state: AuthState,
}

#[derive(Clone, Copy, PartialEq)]
enum AuthState {
    Idle,
    Authenticating,
    Refreshing,
    Cleanup,
}

impl AuthManager {
    fn new() -> Self {
        AuthManager {
            token: SessionToken::allocate(),
            failed_attempts: 0,
            state: AuthState::Idle,
        }
    }

    fn authenticate(&mut self, cred: &[u8]) -> Result<(), &'static str> {
        self.state = AuthState::Authenticating;
        if cred.len() < 8 {
            self.failed_attempts += 1;
            if self.failed_attempts > 3 {
                self.state = AuthState::Cleanup;
            }
            return Err("invalid credentials");
        }
        // Simulate auth check
        let checksum: u8 = cred.iter().fold(0u8, |acc, &b| acc.wrapping_add(b));
        if checksum % 7 == 0 {
            self.token.mark_authenticated();
            self.state = AuthState::Idle;
            Ok(())
        } else {
            self.failed_attempts += 1;
            Err("auth failed")
        }
    }

    fn cleanup_if_needed(&mut self) {
        if self.state == AuthState::Cleanup {
            self.token.release();
            // State transitions to Refreshing to trigger re-allocation
            self.state = AuthState::Refreshing;
        }
    }

    fn try_refresh(&mut self) {
        if self.state == AuthState::Refreshing && self.token.needs_refresh() {
            // Token still has REFRESHABLE tag set (tag bits preserved after set_null)
            // This means needs_refresh() returns true even after release!
            // Attempt to "refresh" by releasing again then reallocating
            self.token.release(); // DOUBLE FREE: data.is_null() checks pointer bits
                                  // but set_null() preserved tag bits, so
                                  // bits == 0x2 (TAG_REFRESHABLE), get_ptr() returns
                                  // (0x2 & !0x3) == 0x0 which IS null...
                                  // Wait - let me re-examine the logic.
            // Actually get_ptr masks off low bits: 0x2 & !0x3 = 0
            // So ptr.is_null() would be true... unless there's an issue
            // in is_null() vs the release guard.

            // The REAL bug: release() checks get_ptr().is_null()
            // but try_refresh gates on needs_refresh() which checks raw bits.
            // After first release: bits = 0x2 (tags preserved)
            // needs_refresh() -> bits & 0x2 != 0 -> TRUE
            // So we enter try_refresh body, but release() would see null ptr.
            // The actual vulnerability is different - see force_refresh below.
            self.token = SessionToken::allocate();
            self.state = AuthState::Idle;
            self.failed_attempts = 0;
        }
    }

    /// Force refresh bypasses the normal refresh path
    fn force_refresh(&mut self) {
        // BUG: checks raw_bits() != 0 instead of is_null()
        // After release, bits = 0x2 (tag preserved), raw_bits() != 0
        // So this thinks the token is still allocated!
        if self.token.data.raw_bits() != 0 {
            let ptr = self.token.data.get_ptr();
            // get_ptr() returns (0x2 & !0x3) = 0x0 = null
            // ... hmm, dealloc on null would be UB but not double-free
            // Let me restructure the vulnerability.
            unsafe { dealloc(ptr, self.token.layout); } // UB: dealloc on null ptr
        }
        self.token = SessionToken::allocate();
        self.state = AuthState::Idle;
    }

    fn run(&mut self, credentials: &[&[u8]]) {
        for cred in credentials {
            let result = self.authenticate(cred);
            self.cleanup_if_needed();
            if result.is_ok() {
                return;
            }
            if self.state == AuthState::Refreshing {
                self.force_refresh();
            }
        }
    }
}

fn main() {
    let mut mgr = AuthManager::new();
    let creds: Vec<&[u8]> = vec![b"ab", b"cd", b"ef", b"gh", b"validcred"];
    mgr.run(&creds);
}
